337→export function renderArtifacts(sessions) {
338→  const lines = ["# Collected artifacts", ""];
339→  if (sessions.length === 0) {
340→    lines.push("No session in the capture carried a tool call. Nothing to attribute against —");
341→    lines.push("**not** an empty result meaning nothing was used.");
342→    return lines.join("\n");
343→  }
344→  for (const s of sessions) {
345→    lines.push(`## ${s.session_key || "(no conversation id)"}`, "");
346→    lines.push(`  ${s.operations.length} operation(s), ${s.test_commands.length} of them checks`);
347→    lines.push(`  task description: ${s.task_description ? `${s.task_description.length} chars` : "not supplied"}`);
348→    lines.push(`  pre-change files: ${Object.keys(s.pre_change_files).length}`);
349→    lines.push("");
350→    for (const op of s.operations.slice(0, 25)) {
351→      const when = op.message_index == null ? op.ordering : `msg[${op.message_index}]`;
352→      const outcome = op.result
353→        ? (op.result.exit_code === null ? "" : ` exit=${op.result.exit_code}`)
354→        : " (no result)";
355→      lines.push(`  [${String(op.seq).padStart(2)}] ${op.kind.padEnd(12)} ${when}  ${op.tool_name || "-"}${outcome}`);
356→      lines.push(`       ${op.locus}`);
357→    }
358→    if (s.operations.length > 25) lines.push(`  … ${s.operations.length - 25} more`);
359→    lines.push("");
360→  }
361→  return lines.join("\n");
362→}
