121→/** Exit status and stderr, read out of a shell tool result envelope. */
122→export function outcomeOf(resultText) {
123→  const s = String(resultText ?? "");
124→  // A real CodeBuddy Bash result spells the tail sections "Exit Code:" (capital
125→  // C) and "Signal:", after "Stderr:"; older shell fixtures used the lowercase
126→  // "Exit code:". Match either, and the negative codes the envelope can carry.
127→  // Matching only the lowercase spelling is why a real capture's exit status
128→  // always read back null.
129→  const code = /(?:^|\n)Exit Code:\s*(-?\d+)/i.exec(s);
130→  // Stderr runs until the next tail section, not to the end of the result —
131→  // otherwise "Exit Code:" and "Signal:" are read back as part of stderr.
132→  const stderr = /(?:^|\n)Stderr:\s*([\s\S]*?)(?=\n(?:Exit Code|Signal):|$)/i.exec(s);
133→  const text = stderr ? stderr[1].trim() : "";
134→  return {
135→    exit_code: code ? Number(code[1]) : null,
136→    stderr: text === "(empty)" ? "" : text.slice(0, 400),
137→  };
138→}
139→
140→/**
141→ * Split a unified diff into hunks, each keeping the file and line range it
142→ * touches — "the token is in the diff" is not a location, "the token is in
143→ * src/proxy.ts lines 40-58" is.
144→ */
145→export function diffHunks(diffText) {
146→  const hunks = [];
147→  let file = "";
148→  let current = null;
149→  for (const line of String(diffText ?? "").split("\n")) {
150→    const plus = /^\+\+\+ [ab]\/(.+)$/.exec(line);
151→    if (plus) { file = plus[1]; current = null; continue; }
152→    const at = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(line);
153→    if (at) {
154→      current = {
155→        file,
156→        start: Number(at[1]),
157→        end: Number(at[1]) + (at[2] ? Number(at[2]) : 1) - 1,
158→        lines: [],
159→      };
160→      hunks.push(current);
161→      continue;
162→    }
163→    if (current && /^[+ -]/.test(line)) current.lines.push(line);
164→  }
165→  return hunks.map((h) => ({ ...h, text: h.lines.join("\n") }));
166→}
167→
168→/**
169→ * Collect every operation in a run, ordered, with calls and results paired.
170→ *
171→ * Messages repeat across turns as the conversation grows. A call is recorded
172→ * once, at the turn it first appeared, so the sequence reflects when things
173→ * happened rather than how many times they were re-sent.
174→ */
175→export function collectArtifacts({ captureEvents = [], taskDescription = "", preChangeFiles = {}, diff = "", runId = null, taskId = null }) {
176→  const bySession = new Map();
177→
178→  const requests = captureEvents
179→    .filter((e) => e?.event === "http.request" && Array.isArray(e?.body?.json?.messages))
180→    .sort((a, b) => String(a.timestamp ?? "").localeCompare(String(b.timestamp ?? "")));
181→
182→  for (const event of requests) {
183→    const sessionKey = normalizeSessionKey(
184→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
185→    );
186→    if (!bySession.has(sessionKey)) bySession.set(sessionKey, { calls: new Map(), results: new Map() });
187→    const store = bySession.get(sessionKey);
188→    const requestId = String(event.requestId ?? "");
189→    const timestamp = String(event.timestamp ?? "");
190→
191→    for (const m of messagesOf(event.body.json)) {
192→      // Key on the call id where there is one. Without it a message can still
193→      // be identified by where it sits, which is stable across turns because
194→      // messages are only ever appended.
195→      const key = m.call_id || `${m.role}@${m.index}`;
196→      const target = m.role === "call" ? store.calls : store.results;
197→      if (target.has(key)) continue; // already seen in an earlier turn
198→      target.set(key, {
199→        ...m,
200→        first_seen_at: timestamp,
201→        locus: `request(${requestId}):msg[${m.index}]${m.call_id ? `:${m.call_id}` : ""}`,
202→      });
203→    }
204→  }
205→
206→  // What the model was *offered* without fetching: the body of every search /
207→  // list result. A discriminative token that appears in one of these reached
208→  // the model as a snippet, not through a full-content read — so a later use of
209→  // it cannot be told apart from having read the snippet. Kept with the message
210→  // index it arrived at, so the judge can screen only what preceded an
211→  // operation. Confirmed necessary by the real run: `47318` came back in 13
212→  // search snippets while `10.244.7.19` came back in none.
213→  // Every tool result's output, not only search results. The first real run
214→  // showed why the narrower version is not enough: the consumer's own
215→  // auto-extracted skill was read at message 4, before any of the credited
216→  // assets. It happened not to carry the discriminative tokens that time —
217→  // but a token delivered by *any* earlier result (another asset's body, a
218→  // file read, a search snippet) means its later use cannot be credited to
219→  // the fetch the judge is looking at. So the judge is given everything that
220→  // arrived, with where it came from, and decides by earliest delivery.
221→  const deliveredBySession = new Map();
222→  for (const event of requests) {
223→    const sessionKey = normalizeSessionKey(
224→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
225→    );
226→    for (const { index, text } of toolResults(event.body.json)) {
227→      const { command, output } = splitCommandAndOutput(text);
228→      if (!output) continue;
229→      const endpoint = commandEndpoint(command);
230→      if (!deliveredBySession.has(sessionKey)) deliveredBySession.set(sessionKey, new Map());
231→      const byIndex = deliveredBySession.get(sessionKey);
232→      // First arrival of a given result is when it was delivered.
233→      if (!byIndex.has(index)) {
234→        byIndex.set(index, {
235→          message_index: index,
236→          endpoint: endpoint || null,
237→          kind: endpoint ? (isListingAction(endpoint) ? "listing" : "fetch") : "other",
238→          // Enough of the command to name the source in a judgement; not the
239→          // full text, which can be long and carries nothing the locus lacks.
240→          source: String(command ?? "").trim().split("\n")[0].slice(0, 160),
241→          text: output,
242→        });
243→      }
244→    }
245→  }
246→  const offeredBySession = new Map();
247→  for (const [sessionKey, byIndex] of deliveredBySession) {
248→    const listings = new Map();
249→    for (const [i, d] of byIndex) if (d.kind === "listing") listings.set(i, d);
250→    offeredBySession.set(sessionKey, listings);
251→  }
252→
253→  const sessions = [];
254→  for (const [sessionKey, store] of bySession) {
255→    const operations = [];
256→    const ordered = [...store.calls.values()].sort((a, b) => a.index - b.index);
257→
258→    ordered.forEach((call, seq) => {
259→      const result = store.results.get(call.call_id) ?? null;
260→      const { command, output } = splitCommandAndOutput(result?.text ?? "");
261→      operations.push({
262→        seq,
263→        kind: TEST_COMMAND.test(call.text) ? "test_command" : "tool_call",
264→        // The position the model wrote this call at. Ordering is judged on it,
265→        // never on the timestamp — see the note at the top of this file.
266→        message_index: call.index,
267→        occurred_at: call.first_seen_at || null,
268→        ordering: "observed",
269→        call_id: call.call_id,
270→        tool_name: call.tool_name,
271→        locus: `${call.locus}:arguments`,
272→        // The arguments are where a token the model *acted on* appears — in the
273→        // mainline scenario the bridge address is inside the curl command here,
274→        // not in anything that came back.
275→        text: call.text,
276→        result: result
277→          ? {
278→              message_index: result.index,
279→              locus: result.locus,
280→              // Kept apart deliberately: the echoed command says what was asked
281→              // for and the output says what came back. Scanning them as one
282→              // blob is how a call that timed out with empty output still
283→              // matched every pattern in its own command.
284→              command_echo: command,
285→              output,
286→              ...outcomeOf(result.text),
287→            }
288→          : null,
289→      });
290→    });
291→
292→    // A diff has no time of its own; it is what the run left behind.
293→    diffHunks(diff).forEach((h, i) => {
294→      operations.push({
295→        seq: operations.length + i,
296→        kind: "diff_hunk",
297→        // No position and no time. "After everything" cannot show the asset was
298→        // read before the edit, because a run that edited first and read after
299→        // leaves exactly this diff.
300→        message_index: null,
301→        occurred_at: null,
302→        ordering: "end_of_run",
303→        call_id: "",
304→        tool_name: "",
305→        locus: `diff:${h.file}:${h.start}-${h.end}`,
306→        text: h.text,
307→        result: null,
308→      });
309→    });
310→
311→    sessions.push({
312→      session_key: sessionKey,
313→      // Stamped by the runner so the judge's events carry them; null when the
314→      // artifacts were collected outside a run. Generalisation is counted as
315→      // distinct task ids, so a missing task id is a missing signal, not zero.
316→      run_id: runId,
317→      task_id: taskId,
318→      task_description: taskDescription,
319→      pre_change_files: preChangeFiles,
320→      diff,
321→      offered_content: [...(offeredBySession.get(sessionKey)?.values() ?? [])]
322→        .sort((a, b) => a.message_index - b.message_index),
323→      // Everything that came back from any tool, in arrival order. The judge
324→      // credits a token to a fetch only when that fetch is the token's
325→      // earliest delivery; anything earlier — another asset's body, a file
326→      // read, a snippet — means the credit cannot be given.
327→      delivered_content: [...(deliveredBySession.get(sessionKey)?.values() ?? [])]
328→        .sort((a, b) => a.message_index - b.message_index),
329→      operations,
330→      test_commands: operations.filter((o) => o.kind === "test_command").map((o) => o.locus),
331→      tool_call_args: operations.filter((o) => o.kind !== "diff_hunk").map((o) => o.text),
332→    });
333→  }
334→  return sessions;
335→}
